mapper.select:
SELECT 
FROM photo_work w
LEFT JOIN photographer p ON w.photographer_id = p.photographer_id

    
        w.work_title LIKE CONCAT('%', #{workTitle}, '%')
    
    
        AND w.photographer_id = #{photographerId}
    
    
        AND p.photographer_name LIKE CONCAT('%', #{photographerName}, '%')
    
    
        AND w.style = #{style}
    
    
        AND w.status = #{status}
    

ORDER BY w.work_id

